mapper.select:
SELECT wo.work_order_id, wo.work_order_no, wo.product_code, wo.product_name, wo.spec_model, wo.unit, wo.plan_qty, wo.finished_qty, wo.qualified_qty, wo.defect_qty, (wo.finished_qty - wo.qualified_qty) AS loss_qty, CASE WHEN wo.finished_qty > 0 THEN ROUND((wo.finished_qty - wo.qualified_qty) / wo.finished_qty * 100, 2) ELSE 0 END AS loss_rate, CASE WHEN wo.finished_qty > 0 THEN ROUND(wo.qualified_qty / wo.finished_qty * 100, 2) ELSE 0 END AS yield_rate, CASE WHEN wo.plan_qty > 0 THEN ROUND(wo.finished_qty / wo.plan_qty * 100, 2) ELSE 0 END AS finish_rate, CASE WHEN wo.finished_qty > 0 THEN ROUND(wo.qualified_qty / wo.finished_qty * 100, 2) ELSE 0 END AS qualified_rate, rpt.actual_hours, rpt.planned_hours, CASE WHEN rpt.actual_hours > 0 THEN ROUND(rpt.planned_hours / rpt.actual_hours * 100, 2) ELSE 0 END AS hour_achieve_rate, wo.status, wo.plan_start, wo.plan_finish, wo.actual_start, disp.last_actual_end AS actual_finish, CASE WHEN wo.status IN ('0','1','2','5') THEN NULL WHEN disp.last_actual_end IS NOT NULL AND wo.plan_finish IS NOT NULL AND disp.last_actual_end <= wo.plan_finish THEN '1' ELSE '0' END AS is_on_time, rpt.report_count FROM mms_work_order wo LEFT JOIN ( SELECT r.work_order_id, SUM(r.good_qty + r.defect_qty) AS actual_hours_placeholder, -- 实际工时暂用报工数量替代（无独立工时字段时用0） 0 AS actual_hours, 0 AS planned_hours, COUNT(*) AS report_count FROM mms_work_report r WHERE r.del_flag = '0' AND r.status = '1' GROUP BY r.work_order_id ) rpt ON rpt.work_order_id = wo.work_order_id LEFT JOIN ( SELECT d.work_order_id, MAX(d.actual_end) AS last_actual_end FROM mms_dispatch d WHERE d.del_flag = '0' AND d.actual_end IS NOT NULL GROUP BY d.work_order_id ) disp ON disp.work_order_id = wo.work_order_id
wo.del_flag = '0' AND wo.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%') AND wo.product_code LIKE CONCAT('%', #{productCode}, '%') AND wo.product_name LIKE CONCAT('%', #{productName}, '%') AND wo.status = #{status}
AND wo.status NOT IN ('0','1','2','5','6') AND disp.last_actual_end IS NOT NULL AND wo.plan_finish IS NOT NULL AND disp.last_actual_end <= wo.plan_finish AND wo.status NOT IN ('0','1','2','5','6') AND disp.last_actual_end IS NOT NULL AND wo.plan_finish IS NOT NULL AND disp.last_actual_end > wo.plan_finish
AND date(disp.last_actual_end) >= #{params.beginTime} AND date(disp.last_actual_end) <= #{params.endTime}
ORDER BY disp.last_actual_end DESC, wo.work_order_id DESC

SELECT COUNT(*) AS work_order_count, COALESCE(SUM(wo.plan_qty), 0) AS total_plan_qty, COALESCE(SUM(wo.finished_qty), 0) AS total_finish_qty, COALESCE(SUM(wo.qualified_qty), 0) AS total_qualified_qty, COALESCE(SUM(wo.finished_qty - wo.qualified_qty), 0) AS total_loss_qty, CASE WHEN SUM(CASE WHEN wo.status IN ('3','4') AND wo.finished_qty > 0 THEN wo.finished_qty ELSE 0 END) > 0 THEN ROUND(SUM(CASE WHEN wo.status IN ('3','4') AND wo.finished_qty > 0 THEN (wo.finished_qty - wo.qualified_qty) ELSE 0 END) / SUM(CASE WHEN wo.status IN ('3','4') AND wo.finished_qty > 0 THEN wo.finished_qty ELSE 0 END) * 100, 2) ELSE 0 END AS avg_loss_rate, CASE WHEN SUM(CASE WHEN wo.status IN ('3','4') AND wo.finished_qty > 0 THEN wo.finished_qty ELSE 0 END) > 0 THEN ROUND(SUM(CASE WHEN wo.status IN ('3','4') AND wo.finished_qty > 0 THEN wo.qualified_qty ELSE 0 END) / SUM(CASE WHEN wo.status IN ('3','4') AND wo.finished_qty > 0 THEN wo.finished_qty ELSE 0 END) * 100, 2) ELSE 0 END AS avg_yield_rate, CASE WHEN SUM(wo.plan_qty) > 0 THEN ROUND(SUM(wo.finished_qty) / SUM(wo.plan_qty) * 100, 2) ELSE 0 END AS avg_finish_rate, CASE WHEN SUM(CASE WHEN wo.status NOT IN ('0','1','2','5','6') THEN 1 ELSE 0 END) > 0 THEN ROUND(SUM(CASE WHEN wo.status NOT IN ('0','1','2','5','6') AND disp.last_actual_end IS NOT NULL AND wo.plan_finish IS NOT NULL AND disp.last_actual_end <= wo.plan_finish THEN 1 ELSE 0 END) / SUM(CASE WHEN wo.status NOT IN ('0','1','2','5','6') THEN 1 ELSE 0 END) * 100, 2) ELSE 0 END AS on_time_rate FROM mms_work_order wo LEFT JOIN ( SELECT d.work_order_id, MAX(d.actual_end) AS last_actual_end FROM mms_dispatch d WHERE d.del_flag = '0' AND d.actual_end IS NOT NULL GROUP BY d.work_order_id ) disp ON disp.work_order_id = wo.work_order_id
wo.del_flag = '0' AND wo.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%') AND wo.product_code LIKE CONCAT('%', #{productCode}, '%') AND wo.product_name LIKE CONCAT('%', #{productName}, '%') AND wo.status = #{status}
AND wo.status NOT IN ('0','1','2','5','6') AND disp.last_actual_end IS NOT NULL AND wo.plan_finish IS NOT NULL AND disp.last_actual_end <= wo.plan_finish AND wo.status NOT IN ('0','1','2','5','6') AND disp.last_actual_end IS NOT NULL AND wo.plan_finish IS NOT NULL AND disp.last_actual_end > wo.plan_finish
AND date(disp.last_actual_end) >= #{params.beginTime} AND date(disp.last_actual_end) <= #{params.endTime}
